const rows = [];
const add = (round, subject, topic, text, options, explanation, source, given = '') => {
  const n = rows.filter(q => q.round === round).length + 1;
  rows.push({ id: `r${round}-${String(n).padStart(2, '0')}`, round, subject, topic, text, options, answer: 0, explanation, source, given });
};

// 44회 확인 주제: 데이터 이해·기획·통계·군집·연관규칙.
add(44,1,'DB 정보 이용','공공 도서관이 이용자가 요청한 자료를 빠르게 검색해 제공하려 한다. 데이터베이스의 어떤 관점이 가장 직접적으로 중요할까?', ['정보 이용 측면','기업의 자본금 규모','개별 저장 장치의 색상','문서 작성자의 직급'], '정보 이용 측면은 이용 목적에 맞는 정보를 신속하게 얻고 활용하는 데 초점을 둔다. 기계 가독성이나 원격 조작성은 정보 축적·전달 관점에서 설명하는 특성이다.','r44a');
add(44,1,'데이터 용량','저장 용량을 SI의 10진 접두어로 계산한다. 3 ZB는 몇 EB인가?', ['3,000 EB','3,072 EB','300 EB','30 EB'], 'SI에서 zetta는 10²¹, exa는 10¹⁸이므로 1 ZB=1,000 EB다. 1,024배를 사용하는 ZiB·EiB 등의 2진 접두어와 구분해야 한다.','r44a');
add(44,1,'데이터 형태','뉴스 페이지를 HTML 파일로 수집했다. 제목·문단의 태그는 있으나 고정된 행과 열의 테이블은 아니다. 가장 일반적인 분류는?', ['반정형 데이터','관계형 정형 데이터만 해당','항상 숫자로만 구성된 정량 데이터','어떠한 구조 정보도 없는 데이터만 해당'], 'HTML은 태그로 구조 정보를 포함하므로 ADsP의 일반적인 분류에서 반정형 데이터로 다룬다. 고정된 스키마의 표와 구조 정보가 없는 자유 텍스트를 구분한다.','r44a');
add(44,1,'연관분석 활용','온라인 문구점이 장바구니 이력에서 노트와 필기구가 함께 담기는 규칙을 찾아 묶음 상품을 제안하려 한다. 가장 직접적인 기법은?', ['연관규칙 분석','시계열의 계절 차분','분산분석의 평균 비교','주성분의 고유값 분해'], '연관규칙은 항목들의 동시 발생 관계를 찾아 추천이나 묶음 판매에 활용한다. 규칙의 발견 자체가 두 상품 사이의 인과관계를 입증하지는 않는다.','r44a');
add(44,1,'회귀분석 활용','식당이 예약 수와 인근 행사 규모로 다음 날 필요한 식재료 무게를 예측하려 한다. 목표값의 성격에 맞는 분석은?', ['회귀분석','고객의 범주만 예측하는 분류','목표값 없이 고객을 묶는 군집','항목의 동시 발생만 찾는 연관분석'], '식재료 무게는 연속형 목표값이므로 회귀를 적용할 수 있다. 분류는 범주형 라벨을 예측하고 군집은 라벨 없이 유사한 대상을 묶는다.','r44a');
add(44,1,'전략적 통찰','분석가가 판매량 예측 결과를 경영진에게 제시하려 한다. 전략적 통찰을 높이는 방법으로 가장 적절한 것은?', ['경쟁 환경과 사업 목표를 함께 고려해 실행 방안을 설명한다','모형의 수식만 전달하고 사업 영향은 생략한다','사내 데이터만으로 외부 환경을 완전히 설명할 수 있다고 가정한다','통계적으로 유의한 결과는 모두 실행해야 한다고 주장한다'], '전략적 통찰은 분석을 기업의 목표와 외부 환경에 연결해 의사결정에 활용하는 역량이다. 통계적 결과만으로 실행의 우선순위나 사업 가치가 자동으로 결정되지는 않는다.','r44a');
add(44,2,'빅데이터 분석 절차','분석 모형의 검증을 마친 팀이 결과를 서비스 시스템에 연결하고 운영 중 성과를 점검하려 한다. 다섯 단계 분석 방법론에서 뒤따르는 단계의 순서는?', ['시스템 구현 → 평가 및 전개','평가 및 전개 → 데이터 준비','데이터 분석 → 분석 기획','데이터 준비 → 시스템 구현 없이 종료'], '빅데이터 분석 방법론의 큰 단계는 분석 기획·데이터 준비·데이터 분석·시스템 구현·평가 및 전개다. 시스템 구현은 모형을 실제 서비스 환경에 적용하는 작업을 포함한다.','r44b');
add(44,2,'분석 거버넌스','각 부서가 서로 다른 고객 수를 보고하고 분석 결과의 승인 책임도 불명확하다. 우선 마련할 관리 체계는?', ['공통 지표 정의와 역할·책임·승인 절차','모든 과제에 같은 회귀식 강제 적용','그림의 색상을 하나로 통일','알고리즘 종류를 매주 무작위 변경'], '거버넌스는 정책·표준·프로세스·역할과 책임 등 분석을 지속적으로 운영하는 체계다. 특정 알고리즘의 선택만으로 지표의 불일치나 책임 문제를 해결할 수 없다.','r44b');
add(44,2,'데이터 가치','위치 데이터의 미래 가치를 현재 시점에 정확히 확정하기 어려운 이유로 가장 적절한 것은?', ['새로운 활용 방식과 다른 데이터와의 결합 효과를 모두 예측하기 어렵다','파일 크기만 알면 모든 사업 가치를 확정할 수 있다','이미 수집된 데이터는 활용 목적에 따라 가치가 달라지지 않는다','데이터에는 새로운 가치가 생길 수 없다'], '데이터의 가치는 이용 맥락과 결합 대상에 따라 달라질 수 있다. 미래의 활용 방식과 기술 변화를 모두 알 수 없으므로 저장 용량만으로 가치를 확정하기 어렵다.','r44b');
add(44,2,'과제 우선순위','두 과제의 기대효과와 실행 위험은 같다고 가정한다. A는 지금 해결해야 하고 쉽게 구현할 수 있으며, B는 내년에 필요하고 구현이 어렵다. 일반적인 우선순위는?', ['A를 먼저 수행한다','B를 먼저 수행해야 한다','난이도가 높을수록 항상 최우선이다','시급성과 난이도를 판단에서 제외한다'], '시급성이 높고 난이도가 낮은 과제는 빠른 성과를 기대할 수 있어 우선 추진하기 좋다. 실제 판단에서는 전략적 중요도·효과·위험·과제 간 선후관계도 함께 고려한다.','r44b');
add(44,2,'분석 기획 데이터 점검','주문 데이터의 고객 코드가 고객 마스터에 존재하지 않는 사례를 발견했다. 기획 단계에서 필요한 조치는?', ['코드 연결의 정합성을 검토하고 원인과 처리 방안을 정한다','모형의 복잡도만 높이면 문제는 사라진다고 가정한다','불일치를 확인하지 않고 그대로 병합한다','분석 목적과 무관하게 모든 고객 행을 삭제한다'], '분석에 사용할 데이터의 정합성·품질·확보 가능성을 기획 단계에서 점검해야 한다. 잘못된 연결은 분석 결과를 왜곡할 수 있어 모형 고도화만으로 해결되지 않는다.','r44b');
add(44,2,'분석 성숙도','팀이 매월 실적 통계와 기본 보고서를 작성하기 시작했지만 예측 결과를 반복적으로 업무에 적용하지는 못한다. 분석 성숙도의 초기 수준에 가장 가까운 것은?', ['도입 단계','최적화 단계','모든 분석이 자동화된 완성 단계','분석을 전혀 하지 않는 단계'], '도입 단계에서는 실적 분석과 통계 작성 등 기초 분석이 시작된다. 이후 활용·확산·최적화로 진행하면서 업무 적용 범위와 분석의 고도화 수준이 커진다.','r44b');
add(44,3,'스피어만 상관','두 평가자가 작품에 매긴 순위의 일치 정도를 평가하려 한다. 스피어만 상관을 적용할 수 있는 핵심 이유는?', ['크기 순서가 있는 자료의 순위 관계를 이용하기 때문이다','작품의 이름을 알파벳 코드로 바꾸면 순서가 자동으로 생기기 때문이다','두 평가 점수가 반드시 정규분포이기 때문이다','스피어만은 모든 비선형 관계를 항상 완벽히 포착하기 때문이다'], '스피어만 상관은 순위에 기반해 단조 관계를 측정한다. 순서 없는 명목 범주에 임의 번호를 붙인 것만으로 의미 있는 순위 관계가 생기지는 않는다.','r44c');
add(44,3,'계통추출','일련번호가 있는 600명의 명단에서 시작 번호를 1~20 중 무작위로 정한 뒤 20명 간격으로 30명을 조사했다. 추출 방법은?', ['계통추출','모든 집단을 조사하는 전수조사','크기에 비례해 집단 전체를 선택하는 집락추출','매번 같은 사람을 뽑는 복원추출'], '무작위 시작점 이후 일정 간격으로 선택하는 방법이 계통추출이다. 명단의 주기적 배열이 조사 특성과 겹치면 표본이 치우칠 수 있으므로 순서를 확인해야 한다.','r44c');
add(44,3,'K-NN 편향·분산','잡음이 많은 이진 분류에서 K-NN의 K를 1에서 훨씬 큰 값으로 바꿨다. 일반적으로 기대되는 변화는?', ['결정 경계가 매끄러워지고 지나치게 크면 과소적합 위험이 생긴다','훈련 자료 한 점의 잡음에 반드시 더 민감해진다','K가 클수록 모델은 항상 과대적합된다','검증 성능은 K와 관계없이 동일하다'], 'K가 커지면 더 많은 이웃을 평균적으로 반영해 잡음의 영향과 분산을 줄일 수 있다. 대신 세부적인 국소 패턴을 놓쳐 편향과 과소적합 위험이 커질 수 있다.','r44c');
add(44,3,'비모수 검정','서로 독립인 두 집단의 순서형 만족도 분포를 정규성 가정 없이 비교하려 한다. 가장 적절한 후보는?', ['만-휘트니 U 검정','항상 등분산 정규성을 요구하는 고전적 t 검정','군집 수를 정하는 엘보 방법','연관규칙의 향상도 계산'], '만-휘트니 U 검정은 두 독립 표본의 순위 정보를 활용하는 비모수 검정이다. 이를 무조건 평균의 차이를 검정한다고 해석하지 말고 비교할 분포와 가정을 확인해야 한다.','r44c');
add(44,3,'중심극한정리','같은 분포에서 독립적으로 추출하고 모집단 분산이 유한하다. 표본 수를 충분히 늘렸을 때 중심극한정리가 설명하는 대상은?', ['적절히 표준화한 표본평균의 분포','개별 관측값의 분포가 반드시 정규분포로 바뀌는 현상','모집단 자체의 분포가 바뀌는 현상','유한한 표본이면 언제나 정확한 정규분포가 되는 현상'], '중심극한정리는 표준화한 합이나 평균의 표본분포가 정규분포에 가까워지는 결과다. 모집단이나 원 관측값의 분포가 정규분포로 변한다는 뜻이 아니다.','r44c');
add(44,3,'시계열 요인','월별 방문자 수가 매년 12월에 반복해서 높아지는 현상을 설명하는 요인은?', ['계절 요인','고정된 주기가 없는 경기 순환만 해당','어떠한 규칙도 없는 불규칙 요인만 해당','장기적 추세만 해당'], '달력과 연결된 일정한 주기의 반복은 계절 요인이다. 순환 요인은 경기 변동처럼 주기가 고정되지 않은 장기적 움직임을 가리키므로 구분해야 한다.','r44c');
add(44,3,'다중공선성','월 기본급과 상여금을 포함한 연 총소득처럼 강하게 상관된 두 변수를 한 회귀모형에 넣자 각각의 계수가 불안정해졌다. 가장 직접적인 원인은?', ['설명변수들 사이의 강한 선형 관계','반응변수가 범주형이라는 사실만','표본 수가 언제나 너무 많다는 것','잔차 평균이 정확히 0이라는 것'], '월 기본급과 연 총소득처럼 관련된 설명변수는 강한 선형 관계로 다중공선성을 만들 수 있다. 이는 개별 회귀계수의 분산을 키워 추정과 해석을 불안정하게 할 수 있다.','r44c');
add(44,3,'마할라노비스 거리','상관이 강한 두 센서값을 이용해 이상 관측을 탐지한다. 변수의 분산과 공분산 구조를 함께 반영하는 거리는?', ['마할라노비스 거리','원래 단위의 맨해튼 거리만','단순히 두 값의 합','관측 순서 번호의 차이'], '마할라노비스 거리는 공분산 행렬의 역행렬을 이용해 변수의 스케일과 상관 구조를 반영한다. 공분산 행렬이 특이하거나 추정이 불안정하면 추가적인 처리가 필요하다.','r44c');
add(44,3,'조건부 확률','구독자 60명 중 18명이 체험 상품을 신청했고, 비구독자 40명 중 8명이 신청했다. 무작위로 선택한 사람이 구독자임을 알 때 신청했을 확률은?', ['0.30','0.18','0.26','0.45'], '구독자라는 조건으로 표본공간을 60명으로 좁혀 18/60=0.30을 계산한다. 전체 신청률 26/100이나 구독자이면서 신청한 비율 18/100과 다르다.','r44d');
add(44,3,'PCA 설명분산','주성분의 고유값이 큰 순서대로 9, 4, 2, 1이다. 앞의 두 주성분이 설명하는 분산 비율은?', ['13/16 = 81.25%','9/16 = 56.25%','13/4 = 325%','2/4 = 50%'], '누적 설명분산 비율은 선택한 주성분의 고유값 합을 전체 고유값 합으로 나눈다. 여기서는 (9+4)/(9+4+2+1)=13/16이며 주성분의 개수 비율과 다르다.','r44d');
add(44,3,'K-means 엘보','군집 수 K를 늘릴 때 군집 내 제곱합이 줄어든다. 엘보 방법이 찾으려는 지점은?', ['K를 더 늘려도 제곱합 감소의 추가 이득이 작아지는 지점','제곱합이 처음으로 음수가 되는 지점','무조건 K가 관측 수와 같은 지점','전체 평균이 가장 큰 지점'], '엘보 방법은 군집 수 증가에 따른 군집 내 제곱합의 감소가 둔화되는 굴곡을 참고한다. 명확한 굴곡이 항상 존재하지 않아 다른 지표와 업무 해석도 함께 확인한다.','r44d');
add(44,3,'독립 사건','사건 A와 B는 독립이며 P(A)=0.4, P(B)=0.25이다. P(A∩B)는?', ['0.10','0.65','0.15','1.60'], '독립이면 동시 발생 확률은 두 확률의 곱이므로 0.4×0.25=0.10이다. 합집합의 확률을 구할 때 쓰는 덧셈 규칙과 혼동하지 않는다.','r44d');
add(44,3,'부트스트랩','서로 다른 관측 20개에서 균등하게 복원추출해 크기 20의 부트스트랩 표본 하나를 만든다. 특정 관측이 한 번도 선택되지 않을 확률은?', ['(19/20)²⁰','1−(19/20)²⁰','(1/20)²⁰','19/20'], '한 번의 추출에서 특정 관측을 피할 확률은 19/20이고 독립적으로 20번 추출하므로 이를 20제곱한다. 1−(19/20)²⁰은 한 번 이상 선택될 확률이다.','r44d');
add(44,3,'Apriori 가지치기','항목집합 {연필, 노트}가 최소 지지도를 충족하지 못했다. Apriori가 이 집합을 포함하는 더 큰 집합을 제외할 수 있는 근거는?', ['상위 집합의 지지도는 부분집합의 지지도보다 클 수 없다','항목이 늘어날수록 지지도가 반드시 증가한다','지지도와 신뢰도는 언제나 같은 값이다','판매 가격이 같으면 모든 집합이 빈발하다'], '상위 집합이 발생한 거래는 그 부분집합도 포함하므로 상위 집합의 지지도는 더 클 수 없다. 비빈발 집합의 모든 상위 집합을 제외하는 성질이 후보 수를 줄인다.','r44d');
add(44,3,'로지스틱 오즈','다른 조건을 고정한 로지스틱 회귀에서 한 설명변수의 계수가 ln(1.8)이다. 그 변수가 1 증가할 때의 해석은?', ['목표 사건의 오즈가 1.8배가 된다','확률이 반드시 80%p 증가한다','오즈가 1.8만큼 더해진다','목표 사건의 확률이 모든 관측에서 1.8배가 된다'], '로지스틱 회귀의 계수는 로그 오즈에 대한 변화이며 exp(계수)가 오즈비다. 오즈는 p/(1−p)이므로 오즈비를 확률의 배수나 확률의 차이로 바로 해석하면 안 된다.','r44d');
add(44,3,'회귀 잔차 자유도','독립 관측 40개로 절편과 설명변수 3개의 선형회귀를 적합했다. 모든 계수가 추정 가능할 때 잔차 자유도는?', ['36','37','39','40'], '추정하는 계수는 절편을 포함해 4개이므로 잔차 자유도는 40−4=36이다. 설명변수 개수만 빼면 절편에 사용된 자유도를 빠뜨리게 된다.','r44d');
add(44,3,'지니 불순도','분류 노드에 성공 3건과 실패 7건이 있다. 이 노드의 지니 불순도는?', ['0.42','0.58','0.30','0.21'], 'Gini=1−Σpᵢ²=1−0.3²−0.7²=0.42다. 이진 분류에서 한 클래스만 있으면 0이고 두 클래스가 절반씩이면 최대 0.5가 된다.','r44c');
add(44,3,'연관규칙 신뢰도','총 200건의 거래 중 A 상품을 포함한 거래가 80건이며 A와 B를 함께 포함한 거래는 28건이다. A→B의 신뢰도는?', ['0.35','0.14','0.40','2.86'], '신뢰도는 A를 구매했다는 조건에서 B도 구매한 비율로 28/80=0.35다. 전체 거래를 분모로 한 28/200=0.14는 지지도다.','r44d');

// 45회 확인 주제: DIKW·무결성·기획 유형·기술통계·분류와 군집.
add(45,1,'DIKW 데이터','택배 운송장마다 적힌 접수 시각과 무게를 가공하지 않고 저장했다. DIKW에서 가장 직접적인 단계는?', ['데이터','정보에서 발견한 일반적 규칙인 지식','최적 정책을 결정한 지혜','사업 실행 계획'], '개별 관측의 사실이나 수치는 데이터에 해당한다. 이를 목적에 맞게 비교·집계해 의미를 부여하는 것은 정보로의 전환이다.','r45a');
add(45,1,'DB 무결성','주문 테이블의 고객 ID는 반드시 고객 테이블에 존재하는 ID여야 한다. 이 조건을 유지하는 핵심 개념은?', ['참조 무결성','데이터의 비휘발성','군집 내 동질성','독립 표본성'], '참조 무결성은 외래키 값이 참조하는 테이블의 유효한 키와 연결되도록 보장한다. 불필요한 중복 제거와는 관련되지만 동일한 개념은 아니다.','r45a');
add(45,1,'유전자 알고리즘','물류센터가 여러 배치안을 개체로 표현하고 좋은 안을 선택해 일부 구역을 교환하며 가끔 임의 변경을 주었다. 사용한 최적화 방식은?', ['유전자 알고리즘','카이제곱 검정','단순 이동평균','상자그림'], '선택·교차·돌연변이는 유전자 알고리즘의 핵심 연산이다. 여러 후보를 세대별로 개선하지만 제한된 탐색에서 전역 최적해를 항상 보장하는 것은 아니다.','r45a');
add(45,1,'데이터 마스킹','고객 연락처를 화면에 표시할 때 가운데 네 자리를 별표로 바꿨다. 가장 직접적으로 적용한 기술은?', ['데이터 마스킹','원본 데이터를 전부 삭제하는 방법','PCA 차원 축소','복원추출'], '마스킹은 민감한 값의 일부 또는 전체를 다른 기호로 가려 노출을 줄이는 방식이다. 일부 문자를 가렸다는 사실만으로 다른 정보와 결합한 재식별 가능성이 완전히 사라지는 것은 아니다.','r45a');
add(45,1,'빅데이터 가치','배송 데이터를 활용한 사업의 성과를 평가한다. 분석 활용의 최종 가치에 가장 가까운 지표는?', ['지연 배송 감소로 고객 경험과 운영 비용이 개선된 정도','저장한 파일의 개수만','모형 코드의 줄 수만','배포한 차트의 색상 수만'], '데이터 활용은 비용 절감·경험 개선·새 서비스 등 실질적 가치를 만드는 데 목적이 있다. 데이터 규모나 기술적 산출물의 개수는 이러한 성과를 직접 보장하지 않는다.','r45a');
add(45,1,'DB 공용 데이터','물품 데이터베이스를 구매팀은 발주에, 회계팀은 비용 정산에 이용한다. 가장 적절한 설명은?', ['같은 데이터라도 사용자의 목적에 따라 함께 활용할 수 있다','모든 사용자는 반드시 동일한 업무만 수행해야 한다','공용 데이터에는 접근 권한을 설정할 수 없다','부서가 다르면 데이터베이스 공유는 불가능하다'], '공용 데이터는 여러 사용자나 응용 프로그램이 공동으로 이용할 수 있는 데이터다. 공동 이용은 사용 목적이나 접근 권한이 모두 같아야 한다는 뜻이 아니다.','r45a');
add(45,2,'분석 주제 통찰','팀은 네트워크 분석 방법을 익혔지만 어느 업무의 관계망에 적용하면 유용할지 탐색 중이다. 대상은 불명확하고 방법은 알려진 분석 유형은?', ['통찰(Insight)','최적화(Optimization)','솔루션(Solution)','발견(Discovery)'], '분석 방법은 알고 대상이 정해지지 않은 유형이 통찰이다. 대상과 방법을 모두 알면 최적화이고 둘 다 불명확하면 발견에 해당한다.','r45b');
add(45,2,'상향식 기획','앱 이용 로그에서 예상하지 못했던 중도 이탈 패턴을 먼저 발견한 뒤 해결할 업무 문제를 정의했다. 가까운 접근 방식은?', ['상향식 접근','미리 정해진 문제에서 시작하는 하향식만 해당','결과 검토 없이 배포하는 방식','아무 관찰도 하지 않는 방식'], '상향식은 데이터 탐색과 관찰에서 패턴이나 기회를 발견하고 분석 과제를 구체화한다. 초기 문제 정의가 명확하지 않을 때도 프로토타입과 검증을 통해 진행할 수 있다.','r45b');
add(45,2,'데이터 거버넌스','조직이 주요 데이터의 담당자를 지정하고 품질 기준·접근 정책·변경 절차를 공통으로 정했다. 이 활동의 묶음은?', ['데이터 거버넌스','단일 모델의 초모수 최적화만','하드디스크를 구매하는 일만','분석가 개인의 메모만'], '데이터 거버넌스는 데이터 관리 정책과 표준, 운영 프로세스, 조직과 책임을 포함한다. 기술 선택도 운영에 관련되지만 장비를 도입하는 것만으로 체계가 완성되지는 않는다.','r45b');
add(45,2,'분석 수준 진단','인력과 분석 환경 등 준비도는 높지만 분석 업무의 활용 경험과 성숙도는 낮다. 준비도×성숙도 진단 유형은?', ['도입형','준비형','정착형','확산형'], '높은 준비도와 낮은 성숙도의 조합은 도입형이다. 둘 다 낮으면 준비형, 준비도 낮음·성숙도 높음은 정착형, 둘 다 높으면 확산형이다.','r45b');
add(45,2,'전략적 필요성','과제 평가자가 “이 문제는 회사의 핵심 사업과 직결되며 방치하면 중요한 계약을 잃을 수 있다”고 설명했다. 가장 가까운 우선순위 기준은?', ['전략적 필요성','데이터 파일의 확장자','개발자 개인의 선호','차트 렌더링 속도만'], '전략적 필요성은 핵심 업무와의 연관성, 해결하지 않았을 때의 위험과 손실 등을 평가한다. 실행 용이성이나 예상 구현 비용과 함께 볼 수 있지만 서로 같은 기준은 아니다.','r45b');
add(45,2,'정확도·복잡도 균형','복잡한 모형의 예측 오차가 조금 낮지만 설명과 운영 비용이 크게 늘었다. 기획 관점에서 적절한 결정 방법은?', ['성능 개선의 가치와 해석·운영 부담을 함께 평가한다','가장 복잡한 모형을 무조건 채택한다','예측 오차는 사업 성과와 전혀 관계가 없다고 가정한다','개발한 날짜가 최신인 모형을 자동 채택한다'], '분석 과제는 정확도뿐 아니라 복잡도·설명 가능성·운영 비용과 적용 목적을 함께 고려해야 한다. 작은 성능 차이가 추가 비용을 정당화하는지는 실제 업무 맥락에서 판단한다.','r45b');
add(45,3,'명목척도','배송 지역을 “동부·서부·남부·북부”로 기록했다. 이 변수의 가장 적절한 척도는?', ['명목척도','서열척도','등간척도','비율척도'], '지역 범주는 구별을 위한 명칭이며 자연스러운 크기 순서가 없으므로 명목척도다. 범주에 숫자 코드를 붙여도 간격이나 비율의 의미가 생기지 않는다.','r45c');
add(45,3,'카이제곱 기대도수','행 합이 40, 열 합이 30, 전체 빈도가 120인 교차표의 한 셀이다. 독립 가설 아래 그 셀의 기대도수는?', ['10','70','30','0.25'], '독립 가설 아래 기대도수는 행 합×열 합/전체 합으로 40×30/120=10이다. 카이제곱 검정은 관측도수와 기대도수의 차이를 기대도수로 가중해 비교한다.','r45c');
add(45,3,'결측값과 기술통계','매출 기록의 결측값을 실제 매출 0원과 동일하게 바꿔 평균을 계산했다. 적절한 평가는?', ['결측 원인과 의미를 확인하지 않은 0 대체는 평균을 왜곡할 수 있다','결측은 언제나 실제 0원이므로 안전하다','0으로 바꾸면 모든 통계량이 원래 값과 같다','결측이 하나라도 있으면 모든 기술통계는 금지된다'], '값이 관측되지 않았다는 것과 실제 값이 0이라는 것은 다르다. 대체 또는 제외 여부는 결측 발생 방식과 분석 목적에 맞게 결정하고 그 영향을 검토해야 한다.','r45c');
add(45,3,'시계열 차분','시간순 관측값이 7, 11, 14, 19이다. 1차 차분을 시간순으로 나열하면?', ['4, 3, 5','7, 11, 14','18, 25, 33','11/7, 14/11, 19/14'], '1차 차분은 현재 값에서 직전 값을 빼므로 11−7=4, 14−11=3, 19−14=5다. 차분은 추세를 제거하는 데 활용되지만 모든 시계열이 한 번의 차분만으로 정상화되지는 않는다.','r45c');
add(45,3,'회귀 예측식','관람 인원 x에 따른 간식 판매량의 회귀식이 ŷ=15+0.6x다. 관람 인원이 50일 때 예측 판매량은?', ['45','30','65','750'], '회귀식에 x=50을 대입하면 15+0.6×50=45다. 절편 15를 빠뜨리면 30이 되며, 예측값은 실제 결과와 항상 일치하는 확정값이 아니다.','r45c');
add(45,3,'후진 제거법','처음에는 모든 후보 설명변수를 포함하고 선정 기준에 따라 하나씩 제거하며 모형을 비교한다. 변수 선택법은?', ['후진 제거법','전진 선택법','데이터의 행을 줄이는 단순추출','주성분의 합을 계산하는 방법'], '후진 제거법은 전체 후보 변수를 포함한 모형에서 출발한다. 전진 선택법은 최소 모형에서 변수를 추가하는 방향이며, 선택된 모형은 검증 자료에서도 평가해야 한다.','r45c');
add(45,3,'PCA와 단위','거리 m와 비용 원처럼 단위와 분산이 크게 다른 변수를 PCA에 사용할 때 적절한 검토는?', ['변수별 표준화가 분석 목적에 맞는지 확인한다','PCA는 원래 데이터 단위를 언제나 자동 제거한다고 가정한다','분산이 큰 변수는 원래 단위와 무관하게 항상 더 중요하다','목표 라벨이 없으면 PCA를 적용할 수 없다'], '공분산 기반 PCA에서는 분산이 큰 변수가 결과를 지배할 수 있다. 변수의 단위 차이가 의미가 없거나 비교 가능한 척도가 필요하면 표준화 또는 상관행렬 기반 분석을 검토한다.','r45c');
add(45,3,'상관 강도','두 자료에서 피어슨 상관계수가 각각 −0.92와 +0.40이었다. 선형 관계의 강도에 대한 올바른 해석은?', ['−0.92인 자료의 선형 관계가 더 강하다','양수이므로 +0.40이 항상 더 강하다','음의 상관은 관계가 없다는 뜻이다','−0.92는 확률이 음수임을 의미한다'], '상관계수의 절댓값이 1에 가까울수록 선형 관계가 강하며 부호는 방향이다. 따라서 0.92가 0.40보다 크지만 이 값만으로 인과관계를 주장할 수는 없다.','r45c');
add(45,3,'회귀와 인과','관찰 자료에서 공부 시간과 성적 사이에 유의한 회귀계수를 얻었다. 가장 적절한 결론은?', ['모형에서 관계를 관찰했지만 인과효과의 증명에는 추가 근거가 필요하다','회귀계수가 유의하면 교란변수는 존재할 수 없다','공부 시간을 늘리는 인과효과가 자동 증명된다','p값이 작으면 자료 수집 방법을 검토할 필요가 없다'], '관찰 자료의 회귀 관계는 교란·선택 편향·역인과 등으로 생길 수 있다. 인과효과를 주장하려면 실험 설계나 인과 추론의 식별 가정 등 별도의 근거가 필요하다.','r45c');
add(45,3,'정밀도','사기 거래로 예측한 50건 중 실제 사기 거래는 35건이었다. 이 결과의 정밀도는?', ['0.70','0.35','0.50','0.30'], '정밀도는 양성으로 예측한 사례 중 실제 양성 비율로 35/50=0.70이다. 재현율을 계산하려면 전체 실제 사기 거래 중 놓친 건수도 알아야 한다.','r45c');
add(45,3,'ROC 좌표','분류 임계값 하나에서 실제 음성 80건 중 8건을 양성으로, 실제 양성 20건 중 16건을 양성으로 예측했다. ROC의 좌표 (FPR, TPR)는?', ['(0.10, 0.80)','(0.80, 0.10)','(0.90, 0.20)','(0.08, 0.16)'], '거짓양성률 FPR=8/80=0.10이고 참양성률 TPR=16/20=0.80이다. ROC의 x축은 1−특이도, y축은 민감도이며 이상적인 점은 (0,1)이다.','r45c');
add(45,3,'배깅','같은 학습 데이터에서 서로 다른 부트스트랩 표본으로 여러 나무를 학습한 뒤 예측을 평균하거나 투표했다. 가장 가까운 앙상블 방식은?', ['배깅','단일 나무의 가지치기만','항상 이전 모델의 오류만 순차 보완하는 부스팅','전체 관측을 한 번 정렬하는 작업'], '배깅은 부트스트랩 표본에서 여러 모델을 적합하고 예측을 결합한다. 부스팅은 앞선 모델의 오류나 잔차를 순차적으로 보완하는 계열이라는 점이 다르다.','r45c');
add(45,3,'나무 가지치기','깊은 분류나무가 훈련 자료는 거의 완벽히 맞추지만 새 자료에서는 오분류가 많다. 가지치기의 기대 효과는?', ['모형 복잡도를 줄여 일반화 성능을 개선할 수 있다','훈련 정확도와 검증 정확도를 반드시 모두 100%로 만든다','입력 자료의 개수를 늘려야만 가능하다','가지치기하면 분류 규칙이 더 복잡해져야 한다'], '가지치기는 분기를 제거해 과적합을 완화하는 방법이다. 훈련 성능은 낮아질 수 있으며 실제 일반화 개선 여부는 검증 자료나 교차검증으로 확인해야 한다.','r45c');
add(45,3,'K-means 적용','고객을 구매 빈도와 평균 주문 금액으로 K-means 군집화하려 한다. 준비 과정에서 가장 적절한 것은?', ['두 변수의 스케일과 이상치 영향을 점검하고 K를 정한다','분석 전에 각 고객의 정답 군집 라벨을 반드시 확보한다','K-means가 K를 항상 자동 결정한다고 가정한다','변수 단위와 초기 중심은 결과에 영향이 없다고 가정한다'], 'K-means는 정해진 K에 대해 군집 내 제곱합을 줄이는 비지도 학습이다. 거리 기반이므로 스케일·이상치·초기 중심의 영향을 받으며 K는 별도로 검토해야 한다.','r45c');
add(45,3,'SOM','고차원 고객 데이터를 2차원 격자에 배치한 SOM에서 비슷한 고객들이 인접한 노드에 나타났다. 핵심 목적은?', ['입력 자료의 위상 관계를 저차원 지도로 표현하는 것','명시적인 정답 없이 분류 정확도 100%를 보장하는 것','각 새 고객마다 격자의 노드 수를 반드시 증가시키는 것','모든 입력을 같은 하나의 값으로 바꾸는 것'], 'SOM은 경쟁 학습과 이웃 노드 갱신을 통해 유사한 입력이 가까운 격자 위치로 가도록 학습한다. 출력 격자는 분석 전에 설계하며 각 입력마다 노드 수가 자동으로 변하는 방식은 아니다.','r45c');
add(45,3,'덴드로그램 절단','네 관측의 계층 군집에서 A와 B는 높이 1, C와 D는 높이 2에서 합쳐지고 두 묶음은 높이 6에서 합쳐졌다. 높이 3에서 자르면 군집 수는?', ['2개','1개','3개','4개'], '높이 3보다 아래에서 A·B와 C·D의 결합이 이미 완료되어 두 묶음이 남는다. 두 묶음의 결합 높이 6까지 올라가지 않았으므로 전체가 하나의 군집은 아니다.','r45c');
add(45,3,'MDS 위치','객체 간 거리를 보존한 MDS 지도를 통째로 회전하거나 평행 이동했다. 가장 적절한 설명은?', ['객체 간 거리 관계는 변하지 않는다','모든 거리가 반드시 두 배가 된다','군집 수가 자동으로 증가한다','각 객체의 지도 좌표는 원래 세계의 절대 좌표를 증명한다'], 'MDS는 객체 사이의 거리·유사성 구조를 저차원에 표현한다. 회전·평행 이동해도 거리는 유지되므로 좌표의 절대 위치나 방향 자체에 고유한 의미가 있다고 단정할 수 없다.','r45c');
add(45,3,'연관규칙 향상도','P(B)=0.50이고 A를 포함한 거래 중 B를 포함한 비율이 0.30이다. A→B의 향상도와 해석은?', ['0.60, 독립일 때보다 함께 나타나는 경향이 낮다','1.67, 양의 연관이다','0.30, 반드시 인과관계가 없다','0.80, 독립이다'], '향상도=P(B|A)/P(B)=0.30/0.50=0.60이다. 1보다 작으면 독립을 가정했을 때보다 동시 발생이 적다는 뜻이며 인과효과를 직접 나타내지는 않는다.','r45c');

// 46회 확인 주제: DB·분석기획·결측·검정·회귀·신경망·평가지표.
add(46,1,'DIKW 정보','동일한 운송 구간의 평균 소요 시간을 비교해 “이번 달에는 지난달보다 15분 짧았다”는 사실을 얻었다. DIKW의 단계는?', ['정보','가공 전 개별 데이터','사업 전반에 일반화된 지식','최적 행동을 결정한 지혜'], '관측을 비교하고 맥락을 부여한 결과는 정보다. 이 결과로 일반적인 원리를 이해하면 지식, 판단과 행동에 활용하면 지혜로 이어진다.','r46a');
add(46,1,'정성·정량 데이터','고객의 자유로운 후기 문장과 별점 1~5를 함께 수집했다. 데이터 성격에 대한 올바른 설명은?', ['후기는 정성적 내용이며 별점은 숫자로 기록돼도 순서형 평가다','후기 문장은 항상 정량 데이터다','별점의 4점은 2점보다 만족도가 정확히 두 배임을 뜻한다','문장은 컴퓨터에 저장할 수 없다'], '후기 문장은 경험과 의견을 담는 정성적 데이터다. 숫자를 사용했다고 모든 변수가 등간·비율 척도가 되는 것은 아니며 별점의 순서와 간격 의미를 구분해야 한다.','r46a');
add(46,1,'DB 통합 데이터','세 지점이 같은 공급자의 정보를 따로 관리해 주소가 서로 다르게 기록됐다. 중복을 줄이고 공통 식별자로 통합한 목적은?', ['데이터의 일관성을 높여 공동 이용하기 위해','모든 사용자가 같은 화면만 보게 하기 위해','시간에 따른 변경 이력을 반드시 없애기 위해','자료를 저장할 수 없게 만들기 위해'], '통합은 같은 대상의 불필요한 중복을 줄이고 일관된 구조로 관리하는 데 도움이 된다. 물리적 서버가 하나여야 하거나 모든 사용자 목적이 같아야 하는 것은 아니다.','r46a');
add(46,1,'OLTP','공연 예매 서비스가 좌석을 예약·취소하고 결제 내역을 즉시 갱신한다. 이러한 일상 거래 처리를 중심으로 하는 것은?', ['OLTP','장기 매출을 다차원으로 집계하는 OLAP','주성분 분석','연관규칙의 신뢰도'], 'OLTP는 주문·예약·결제 등 많은 짧은 거래의 입력과 갱신을 처리한다. OLAP는 의사결정용 집계와 다차원 분석에 초점을 둔다.','r46a');
add(46,1,'ETL','여러 시스템의 날짜 표기와 화폐 단위를 공통 기준으로 변환한 뒤 분석 저장소에 넣었다. ETL의 T에 해당하는 작업은?', ['변환(Transform)','추출(Extract)만','적재(Load)만','분류 정확도 평가'], 'Transform 단계에서 형식 통일·정제·결합·파생 값 계산 등 목적에 맞게 데이터를 변환한다. 추출은 원천에서 가져오는 작업이고 적재는 대상 저장소에 기록하는 작업이다.','r46a');
add(46,1,'분류 분석','과거 장비 기록에 정상·고장이라는 라벨이 있다. 새 장비 기록이 어느 라벨에 속하는지 예측하려 한다. 가장 직접적인 분석은?', ['분류','연속형 판매액만 예측하는 회귀','라벨 없이 대상을 묶는 군집','동시 구매 규칙만 찾는 연관분석'], '분류는 라벨이 있는 자료를 학습해 새 대상의 범주를 예측한다. 고장 위험을 확률로 출력하더라도 목표 범주가 정상·고장인 분류 문제라는 점은 변하지 않는다.','r46a');
add(46,2,'분석 주제 최적화','이미 분석할 업무와 사용할 예측 기법이 정해져 있고, 기존 운영의 효율을 더 높이는 과제를 수행한다. 분석 주제 유형은?', ['최적화','솔루션','통찰','발견'], '분석 대상과 방법을 모두 아는 경우 개선을 통한 최적화 유형이다. 대상만 알면 솔루션이고 방법만 알면 통찰이다.','r46b');
add(46,2,'CRISP-DM 사업 이해','불량 탐지 프로젝트가 시작됐다. CRISP-DM 사업 이해 단계에서 먼저 할 일로 적절한 것은?', ['불량 탐지로 해결할 업무 목표와 성공 기준을 명확히 한다','운영 서버에 최종 모델을 즉시 배포한다','비즈니스 비용을 확인하지 않고 정확도만 최대화한다','모델 계수를 최종 확정한다'], '사업 이해는 업무 목적과 제약, 분석 목표 및 계획을 정의하는 출발점이다. 기술적 지표만 높아도 현장의 오류 비용이나 운영 요구를 충족하지 못할 수 있다.','r46b');
add(46,2,'분석 과제 정의서','지역 수요 예측 과제에서 사내 주문 기록과 외부 행사 일정이 모두 유용하다. 과제 정의서 작성 방식으로 적절한 것은?', ['목표·범위·활용 결과와 함께 내외부 데이터의 확보 조건을 명시한다','외부 데이터는 무조건 제외한다','최신 알고리즘 이름만 쓰고 목표는 생략한다','어떤 데이터든 품질과 이용 조건을 검토할 필요가 없다'], '과제 정의서는 분석 목적·범위·주요 결과와 필요한 데이터 및 제약을 구체화한다. 내부와 외부 구분만으로 적합성이 결정되지는 않아 확보 가능성·품질·활용 조건을 함께 검토한다.','r46b');
add(46,2,'정확성과 정밀성','동일한 양을 반복 추정했더니 결과끼리는 매우 비슷하지만 실제 기준값과는 꾸준히 멀었다. 이 측정 결과의 성격은?', ['정밀성은 높지만 정확성은 낮다','정확성과 정밀성이 모두 높다','정밀성은 낮지만 정확성은 높다','결과끼리 비슷하면 실제값과도 반드시 가깝다'], '측정 맥락의 정확성은 기준값과의 가까움, 정밀성은 반복 결과끼리의 일관성이다. 반복적으로 같은 방향으로 벗어나는 편향이 있으면 정밀해도 정확하지 않을 수 있으며 분류 지표의 precision과는 구분한다.','r46b');
add(46,2,'상향식 프로토타입','사업 문제가 구체화되지 않은 데이터에서 작은 시제품을 만들어 사용자의 반응을 확인했다. 이 접근이 도움이 되는 이유는?', ['탐색과 피드백으로 문제와 해결 가능성을 점진적으로 구체화할 수 있다','문제가 확정되지 않았으면 어떠한 탐색도 해서는 안 된다','모든 데이터 구조가 확정돼 있어야만 상향식 접근이 가능하다','프로토타입의 결과는 검증 없이 최종 사실이다'], '상향식에서는 탐색과 프로토타이핑으로 패턴·기회·요구사항을 발견한다. 시제품은 가설을 확인하기 위한 수단이며 결과를 검증하고 필요하면 반복 개선해야 한다.','r46b');
add(46,2,'우선순위와 선행 과제','매우 시급한 예측 과제 A가 있지만 필수 데이터 수집 과제 B가 완료돼야 수행할 수 있다. 적절한 계획은?', ['A의 시급성을 고려하되 B와의 선후관계를 반영해 추진한다','A가 시급하므로 필수 데이터 없이 즉시 완성할 수 있다고 가정한다','선행 과제는 모든 경우 우선순위에서 제외한다','시급성만으로 모든 실행 순서를 확정한다'], '시급성과 난이도는 우선순위의 중요한 기준이지만 실행 의존성도 반영해야 한다. 필수 선행 작업을 무시하면 높은 우선순위의 과제도 실제로 진행하지 못할 수 있다.','r46b');
add(46,3,'결측값 대체','학습 자료와 검증 자료를 나눈 뒤 수치형 결측을 중앙값으로 대체하려 한다. 데이터 누출을 막는 절차는?', ['학습 자료에서 중앙값을 구해 두 자료의 대체에 적용한다','검증 자료의 목표 라벨로 결측값을 채운다','모든 자료를 합쳐 목표 라벨까지 보고 대체 규칙을 만든다','검증 점수가 가장 높아지는 정답값을 결측에 직접 넣는다'], '전처리에서 추정하는 중앙값 등도 학습 자료만으로 계산하고 검증 자료에 적용해야 한다. 검증 자료의 정보를 학습에 이용하면 실제 성능을 과대평가하는 데이터 누출이 생길 수 있다.','r46c');
add(46,3,'가설검정 판단','사전에 정한 유의수준은 0.05이며 검정의 p값이 0.08이다. 가장 적절한 판단은?', ['귀무가설을 기각하지 못한다','귀무가설이 참임을 확정한다','대립가설이 참일 확률은 0.92다','p값이 0.05보다 크므로 귀무가설을 기각한다'], 'p값 0.08은 유의수준 0.05보다 커 귀무가설을 기각할 근거가 충분하지 않다. 기각하지 못했다는 결과가 귀무가설이 참이라고 증명한 것은 아니다.','r46c');
add(46,3,'모수와 통계량','전체 반품 상품의 평균 무게 μ를 추정하려고 표본 100개의 평균 무게를 계산했다. 구분으로 올바른 것은?', ['μ는 모수이고 표본에서 계산한 평균은 통계량이다','μ는 통계량이고 표본평균은 모수다','표본평균은 자료를 얻기 전부터 알려진 상수다','모집단 평균과 표본평균은 언제나 정확히 같다'], '모수는 모집단의 특성이며 통계량은 표본의 함수로 계산한다. 표본이 바뀌면 표본평균도 달라질 수 있으므로 이를 이용한 추정에는 불확실성이 있다.','r46c');
add(46,3,'이산 기댓값','하루 문의 건수 X가 0, 1, 3이고 각각의 확률이 0.2, 0.5, 0.3이다. E(X)는?', ['1.4','1.0','1.5','4.0'], '기댓값은 가능한 값과 확률의 곱을 합해 0×0.2+1×0.5+3×0.3=1.4다. 값이 나올 확률을 고려하지 않고 가능한 값만 평균내는 것은 다르다.','r46c');
add(46,3,'결정계수','절편이 있는 최소제곱 회귀에서 회귀제곱합 SSR=63, 잔차제곱합 SSE=27이다. 결정계수 R²는?', ['0.70','0.30','2.33','0.90'], '전체제곱합 SST=SSR+SSE=90이므로 R²=SSR/SST=63/90=0.70이다. 잔차 비율 SSE/SST=0.30은 설명되지 않은 변동의 비율이다.','r46c');
add(46,3,'일표본 t 통계량','독립 표본 25개의 평균이 104, 표본표준편차가 10이다. 귀무가설 μ=100에 대한 t 통계량은?', ['2','0.4','10','20'], '표준오차는 10/√25=2이고 t=(104−100)/2=2다. p값이나 기각 여부를 판단하려면 자유도 24와 단측·양측 가설을 함께 확인한다.','r46c');
add(46,3,'사분위수 범위','처리 시간 자료의 제1사분위수가 18분, 제3사분위수가 29분이다. 중앙 50%의 산포를 나타내는 IQR은?', ['11분','23.5분','47분','29분'], 'IQR은 Q3−Q1=29−18=11분이다. 두 사분위수의 평균은 IQR이 아니며 전체 범위는 최댓값과 최솟값이 있어야 계산할 수 있다.','r46c');
add(46,3,'표본 공분산','관측 쌍 (X,Y)가 (1,3), (3,4), (5,8)이다. 분모 n−1을 쓰는 표본 공분산은?', ['5','10/3','10','1'], '평균은 X̄=3, Ȳ=5이고 편차 곱의 합은 (−2)(−2)+0(−1)+2×3=10이다. 표본 공분산은 10/(3−1)=5이며 분모 n을 쓰는 계산과 구분한다.','r46c');
add(46,3,'PCA 차원 상한','관측 6개, 변수 8개인 자료를 평균 중심화해 PCA를 수행한다. 0이 아닌 분산을 갖는 주성분의 최대 개수는?', ['5개','6개','8개','48개'], '중심화된 자료 행렬의 계수는 최대 min(n−1,p)이므로 min(5,8)=5다. 실제 선형 종속이 더 있으면 0이 아닌 주성분 수는 이보다 작아질 수 있다.','r46c');
add(46,3,'데이터 마이닝 절차','팀이 고객 행동 자료에 여러 기법을 적용하려 한다. 올바른 출발점은?', ['해결할 목적을 정의하고 필요한 자료를 준비한다','기법부터 무작위로 선택하고 목적은 결과를 본 뒤 꾸민다','모델 검증을 생략한다','원천 자료를 폐기한 후 데이터 준비를 시작한다'], '데이터 마이닝은 목적 정의 뒤 데이터 준비와 가공, 기법 적용, 검증으로 이어진다. 모델의 결과가 목표와 맞는지 확인해야 하므로 기법 사용 자체가 분석의 목적은 아니다.','r46c');
add(46,3,'약정상성','약정상 시계열의 특징으로 가장 적절한 것은?', ['평균과 분산이 시간에 일정하고 공분산은 두 시점의 시차에만 의존한다','평균은 시간에 따라 반드시 증가한다','모든 시차의 자기상관이 1이다','자기상관이 존재하면 반드시 비정상이다'], '약정상성은 평균·분산의 일정성과 시차에 따른 공분산 구조를 뜻한다. 정상 시계열도 시차별 자기상관을 가질 수 있으며 백색잡음과 동일한 개념은 아니다.','r46c');
add(46,3,'로지스틱 계수','불량 여부에 대한 로지스틱 회귀에서 온도 변수의 exp(계수)가 0.6이다. 다른 변수를 고정한 적절한 해석은?', ['온도가 1 증가하면 불량 오즈가 40% 감소한다','불량 확률이 모든 경우 40%p 감소한다','온도가 1 증가하면 불량 확률이 반드시 0이 된다','불량 오즈가 60% 증가한다'], '오즈비 0.6은 기준 오즈의 60%가 되어 오즈가 40% 감소한다는 뜻이다. 확률의 변화량은 기존 확률에 따라 달라지므로 오즈의 감소율과 같다고 단정할 수 없다.','r46c');
add(46,3,'지도 분류','이미 정상 메일과 스팸 메일로 표시된 예시로 모형을 만든 뒤 새 메일의 범주를 예측한다. 설명으로 올바른 것은?', ['라벨이 있는 자료를 이용하는 지도 분류다','라벨을 이용하지 않는 순수 군집이다','연속값만 예측하는 회귀만 가능하다','학습 예시 없이 모든 규칙이 자동으로 정답이 된다'], '분류는 알려진 범주를 학습해 새 관측의 범주를 예측하는 지도 학습이다. 훈련 자료에서의 성능만으로 실제 일반화 성능을 확정하지 말고 별도 검증을 해야 한다.','r46c');
add(46,3,'시그모이드 범위','표준 시그모이드 σ(z)=1/(1+e^(−z))에 유한한 실수 z를 넣었다. 출력 범위는?', ['0보다 크고 1보다 작다','−1 이상 1 이하의 모든 실수다','항상 0 또는 1만 나온다','0보다 작은 값만 나온다'], '유한한 z에서는 지수값이 양수여서 시그모이드는 열린 구간 (0,1)의 값을 갖는다. 0과 1은 입력이 무한대로 가는 극한에서 접근하는 값이다.','r46c');
add(46,3,'신경망 연결 수','입력 노드 4개, 은닉 노드 5개, 출력 노드 2개인 완전연결 신경망이다. 편향을 제외한 연결 가중치 수는?', ['30개','11개','40개','37개'], '입력→은닉 연결은 4×5=20개, 은닉→출력은 5×2=10개이므로 합계 30개다. 편향을 포함하라는 조건이라면 은닉·출력의 7개를 추가해야 한다.','r46c');
add(46,3,'Softmax','세 범주에 대한 로짓이 모두 0이다. Softmax를 적용한 각 범주의 확률은?', ['모두 1/3','모두 0','모두 1','첫 범주만 1이고 나머지는 0'], 'Softmax는 e^zᵢ를 모든 e^z의 합으로 나누므로 1/(1+1+1)=1/3이다. 각 출력이 양수이고 합이 1이어서 다중 분류의 확률 표현에 사용한다.','r46c');
add(46,3,'재현율','실제 불량품이 100개였고 모형이 이 중 80개를 불량으로 탐지했다. 재현율은?', ['0.80','0.20','1.25','탐지한 전체 제품 수가 없으므로 계산 불가'], '재현율=TP/(TP+FN)=80/100=0.80이다. 탐지한 전체 제품 수가 필요한 지표는 정밀도이며, 실제 불량 중 놓친 것은 20개다.','r46c');
add(46,3,'완전연결 군집','군집 A와 B에 속하는 점 쌍 사이의 거리가 2, 3, 4, 5로 주어졌다. 완전연결법의 두 군집 거리는?', ['5','2','3.5','14'], '완전연결법은 두 군집의 모든 점 쌍 거리 중 최댓값을 사용하므로 5다. 단일연결법은 최솟값 2, 평균연결법은 평균 3.5를 사용한다.','r46c');

// 47회 확인 주제: 지식전환·DB·거버넌스·표본오차·시계열·EM.
add(47,1,'SECI 외재화','기술자가 머릿속에만 있던 장비 조정 요령을 도식과 설명서로 표현했다. SECI의 지식 전환은?', ['외재화: 암묵지에서 형식지로','공통화: 암묵지에서 암묵지로','연결화: 형식지에서 형식지로','내재화: 형식지에서 암묵지로'], '경험과 직관 같은 암묵지를 명시적인 문서나 모형으로 표현하는 전환은 외재화다. 작성된 설명서를 실습으로 체득하는 역방향은 내재화다.','r47a');
add(47,1,'DIKW 지식','여러 번의 운영 결과를 종합해 “상담 대기 시간이 길수록 이탈이 늘어나는 경향이 있다”는 일반적 규칙을 이해했다. DIKW 단계로 가장 가까운 것은?', ['지식','개별 관측값인 데이터','실행할 정책을 이미 결정한 지혜','파일의 물리적 용량'], '여러 정보의 관계를 이해하고 일반적인 규칙으로 정리하는 것은 지식에 가깝다. 이 규칙을 활용해 실제 행동을 판단하는 단계는 지혜이며 관찰 관계가 곧 인과라는 뜻은 아니다.','r47a');
add(47,1,'DB 축적·전달','디지털 기록이 컴퓨터에서 읽히고 검색되며 다른 지역에서도 접근될 수 있다. 이 특성들을 묶어 설명하는 DB 관점은?', ['정보의 축적 및 전달 측면','모형의 분류 정확도 측면','실험의 무작위 배정 측면','군집 내 거리 최소화 측면'], '기계 가독성·검색 가능성·원격 조작성은 데이터베이스의 정보 축적과 전달 측면의 대표적 특성이다. 자료를 갖추었다는 사실만으로 원하는 이용 목적을 충족하는지는 별도로 확인해야 한다.','r47a');
add(47,1,'익명화와 재식별','분석 자료에서 이름을 지웠지만 생년월일·상세 위치·외부 명단을 결합하면 특정 사람을 알아낼 수 있다. 적절한 평가는?', ['이름 삭제만으로 재식별 위험이 사라졌다고 단정할 수 없다','이름이 없으면 어떤 경우에도 익명성이 보장된다','숫자 데이터는 개인정보와 연결될 수 없다','변수 수를 늘리면 재식별이 언제나 불가능해진다'], '직접 식별자를 제거해도 준식별자나 외부 자료와의 결합으로 재식별이 가능할 수 있다. 익명성은 남은 정보와 결합 가능성을 함께 평가해야 하며 기술 하나의 적용만으로 확정되지 않는다.','r47a');
add(47,1,'OLTP와 OLAP','은행의 실시간 계좌이체와 여러 해의 지역별 거래 추이 분석을 각각 맡길 처리 유형은?', ['계좌이체는 OLTP, 추이 분석은 OLAP','계좌이체는 OLAP, 추이 분석은 OLTP','둘 다 반드시 주성분 분석','둘 다 데이터 없이 수행하는 처리'], 'OLTP는 현재 거래의 입력·변경을 신속하고 일관되게 처리하는 데 초점을 둔다. OLAP는 누적 데이터를 다양한 차원에서 조회·집계해 의사결정을 지원한다.','r47a');
add(47,1,'데이터 사이언티스트 역량','높은 검증 성능을 얻은 분석가가 현업 담당자의 업무 흐름을 이해하고 결과의 한계를 설명하려 한다. 이 활동의 가치는?', ['소프트 스킬로 분석을 실제 의사결정과 협업에 연결한다','코딩 능력이 있으면 의사소통은 필요 없다','모델의 수치 결과는 사업 맥락과 관계없다','검증 성능이 높으면 한계를 설명하면 안 된다'], '데이터 사이언티스트는 기술 역량과 함께 의사소통·협업·사업 이해가 필요하다. 결과의 의미와 한계를 전달해야 현업이 적절하게 활용하고 실행 조건을 조율할 수 있다.','r47a');
add(47,2,'분석 기획 성공 기준','재고 예측의 성능 지표는 좋아졌지만 담당자가 결과를 사용할 시점보다 늦게 전달받는다. 기획에서 빠뜨린 사항은?', ['업무 활용 시점과 운영 제약을 포함한 성공 기준','더 복잡한 모델 이름','화면 색상 수','학습 자료의 파일 이름 길이'], '분석 기획은 예측 정확도뿐 아니라 활용 방식·시점·운영 제약을 목표와 연결해야 한다. 필요한 시점에 사용하지 못하는 결과는 좋은 성능 수치가 있어도 사업 성과로 이어지기 어렵다.','r47b');
add(47,2,'반정형 데이터','IoT 장비가 센서값과 시각을 키-값과 중첩 구조가 있는 JSON 로그로 보낸다. 이 파일 형식의 일반적 분류는?', ['반정형 데이터','형식과 관계없이 모든 IoT 데이터는 정형','오직 그림으로 구성된 비정형','순서만 있는 서열척도'], 'JSON은 키와 중첩 구조 등 메타 정보를 포함하는 반정형 형식이다. IoT라는 생성 원천만으로 형식을 결정하지 말고 실제 스키마와 저장 구조를 확인해야 한다.','r47b');
add(47,2,'분석 주제 솔루션','배송 지연이라는 분석 대상과 해결 목표는 명확하지만 어떤 기법을 사용할지는 아직 모른다. 분석 주제 유형은?', ['솔루션','최적화','통찰','발견'], '대상을 알고 방법을 모르는 경우가 솔루션 유형이다. 대상과 방법 모두 알면 최적화, 대상 모르고 방법 알면 통찰, 둘 다 모르면 발견이다.','r47b');
add(47,2,'분석 마스터플랜','회사 전체의 분석 과제들을 전략적 효과와 실행 가능성에 따라 배치하고 중장기 추진 순서를 정했다. 이 계획의 성격은?', ['분석 마스터플랜','개별 회귀계수의 t 검정','단일 자료의 산점도','하나의 범주만 바꾸는 인코딩'], '마스터플랜은 여러 과제의 우선순위와 이행 로드맵을 전사 관점에서 수립한다. 개별 과제의 기대 성과뿐 아니라 전략적 중요도·실행 용이성·선후관계를 함께 검토한다.','r47b');
add(47,2,'집중형 분석 조직','분석 인력이 전담 부서에 모여 전사 우선순위에 따라 각 부서의 요청을 수행한다. 조직 형태는?', ['집중형','분산형','현업 부서마다 별도로 분석하는 기능형','분석 담당자가 없는 조직'], '집중형은 별도 전담조직이 분석 기능을 모아 전사적으로 수행하는 형태다. 공통 역량과 자원 관리에 유리할 수 있지만 현업과의 소통과 병목 관리가 필요하다.','r47b');
add(47,2,'데이터 거버넌스 협업','고객 데이터 표준을 정하는 과정에서 현업과 IT가 각자 다른 규칙을 적용했다. 적절한 개선 방향은?', ['공통 정책과 책임을 정하고 업무·시스템 프로세스를 함께 관리한다','거버넌스를 IT와 완전히 분리해 정보 교환을 막는다','부서별 충돌을 기록하지 않고 그대로 둔다','표준은 일단 정하면 어떠한 변경도 검토하지 않는다'], '거버넌스는 현업·IT·관리 조직의 역할과 책임을 연결해 일관된 데이터 관리를 지원한다. 정책과 시스템 운영이 분리되면 표준의 실제 적용이나 품질 문제 해결이 어려워질 수 있다.','r47b');
add(47,3,'비율척도','물품의 질량을 kg 단위로 측정했다. 0kg과 4kg 대 2kg의 의미를 함께 고려할 때 척도는?', ['비율척도','명목척도','서열척도','등간척도만 해당'], '질량은 물리적인 0과 배수 비교가 의미 있는 비율척도다. 섭씨 온도처럼 0이 임의 기준인 등간척도에서는 같은 배수 해석을 할 수 없다.','r47c');
add(47,3,'EDA 역할','처음 받은 자료에서 분포·결측·이상치·변수 간 패턴을 그림과 요약통계로 살펴본다. 가장 가까운 목적은?', ['자료를 이해하고 이후 분석의 가설과 점검 사항을 발견한다','사업 목표 달성 여부를 최종 승인하는 일만','정답을 확인하지 않고 모든 모형을 배포하는 일','이미 발견한 관계가 인과임을 자동 입증하는 일'], '탐색적 데이터 분석은 자료의 특성과 구조를 파악하고 문제나 가설을 발견하는 과정이다. 탐색에서 얻은 패턴은 이후 검증해야 하며 최종 운영 승인과 동일한 단계가 아니다.','r47c');
add(47,3,'박스플롯 경계','Q1=5, Q3=17인 자료에 1.5×IQR 규칙을 적용한다. 이상치 후보를 구분하는 하한·상한 경계는?', ['−13, 35','5, 17','−7, 29','−18, 40'], 'IQR=17−5=12이므로 하한은 5−18=−13, 상한은 17+18=35다. 이 경계는 이상치 후보 판단 기준이며 실제 관측의 최솟값·최댓값이나 수염 끝과 항상 같지는 않다.','r47c');
add(47,3,'제1종 오류','귀무가설이 “새 포장 방식의 효과가 없다”이고 실제로도 효과가 없다. 검정에서 이를 기각해 효과가 있다고 결론내렸다. 오류 유형은?', ['제1종 오류','제2종 오류','반드시 오류가 없는 판단','과소적합의 정의'], '제1종 오류는 참인 귀무가설을 기각하는 오류다. 거짓인 귀무가설을 기각하지 못하는 것은 제2종 오류이며 유의수준은 제1종 오류를 통제하는 기준이다.','r47c');
add(47,3,'비표본오차','표본 수를 크게 늘렸지만 특정 연령대가 설문에 거의 응답하지 않고 질문 문구도 답을 유도했다. 올바른 설명은?', ['무응답과 측정 편향은 표본 수 증가만으로 없어지지 않는다','표본 수를 늘리면 모든 비표본오차가 반드시 사라진다','전수조사는 질문 문구의 영향을 전혀 받지 않는다','표본 수와 무관하게 표본오차는 언제나 정확히 0이다'], '무응답·측정·입력·처리 등에서 생기는 오류는 비표본오차다. 표본 수가 커져도 체계적인 편향은 남을 수 있어 설계와 수집·처리의 품질 관리가 필요하다.','r47c');
add(47,3,'평균과 중앙값','자료가 1, 2, 2, 3, 12이다. 평균과 중앙값 및 큰 값의 영향에 대한 올바른 설명은?', ['평균 4, 중앙값 2이며 평균이 큰 값 12의 영향을 더 받는다','평균 2, 중앙값 4이며 중앙값만 12의 영향을 받는다','평균과 중앙값 모두 12다','평균과 중앙값은 언제나 같아야 한다'], '평균은 (1+2+2+3+12)/5=4이고 정렬된 가운데 값은 2다. 평균은 모든 크기를 이용하기 때문에 큰 값의 영향을 받으며 중앙값은 상대적으로 강건하다.','r47c');
add(47,3,'단조 관계와 상관','X가 1, 2, 3, 4이고 Y가 1, 4, 9, 16이다. 두 변수의 스피어만 상관에 대한 올바른 설명은?', ['두 순위가 일치하므로 +1이다','직선 관계가 아니므로 반드시 0이다','Y가 증가하므로 −1이다','모든 비선형 자료에서는 계산할 수 없다'], 'X와 Y는 같은 순서로 엄격히 증가하므로 순위가 완전히 일치해 스피어만 상관은 +1이다. 스피어만은 단조 관계를 측정하며 U자형 등 모든 비선형 관계를 포착하는 지표는 아니다.','r47c');
add(47,3,'p값 해석','유의수준 0.01인 검정에서 p=0.004를 얻었다. 가장 적절한 설명은?', ['귀무가설을 기각하지만 효과 크기나 사업 중요도는 별도 평가한다','귀무가설이 참일 확률이 정확히 0.004다','실제 효과는 반드시 매우 크다','귀무가설을 99.6%의 확률로 틀렸다고 증명했다'], 'p값이 0.01보다 작아 정한 기준에서 귀무가설을 기각한다. p값은 귀무가설 자체의 참일 확률이나 효과의 크기를 나타내지 않으므로 추정치·구간·맥락을 함께 봐야 한다.','r47c');
add(47,3,'회귀 잔차 평균제곱','절편과 설명변수 2개가 있는 선형회귀를 관측 12개로 적합했다. 모형이 완전계수이고 SSE=27일 때 잔차 평균제곱 MSE는?', ['3','2.25','2.7','9'], '추정 계수는 3개이므로 잔차 자유도는 12−3=9이며 MSE=SSE/9=3이다. 이 문제의 MSE는 잔차 평균제곱으로, 단순히 관측 수로 나눈 예측오차 평균과 분모가 다르다.','r47c');
add(47,3,'다중공선성 대응','설명변수들이 서로 매우 상관돼 회귀계수 추정이 불안정하다. 적절한 대응 후보는?', ['중복 변수를 정리하거나 릿지와 같은 규제를 검토한다','목표값이 연속형이어도 무조건 로지스틱 회귀로 바꾼다','계수의 표준오차가 영향받지 않는다고 가정한다','같은 변수를 여러 번 복제해 추가한다'], '변수 선택·정보 결합·주성분 회귀·릿지 같은 방법은 공선성에 대응하는 후보가 될 수 있다. 분석 목적과 예측·해석의 균형을 고려하며 로지스틱으로 변경하는 것 자체가 공선성 해결책은 아니다.','r47c');
add(47,3,'회귀계수 조건부 해석','배송시간을 거리와 교통량으로 설명한 모형에서 거리의 계수가 2분/km다. 모형에 맞는 해석은?', ['교통량을 고정하면 거리가 1km 늘 때 예측 배송시간은 2분 늘어난다','모든 실제 배송시간이 반드시 정확히 2분 늘어난다','거리와 교통량을 동시에 1씩 바꾼 효과가 2분이다','거리의 계수만으로 거리의 인과효과가 증명된다'], '다중회귀의 한 계수는 다른 설명변수를 고정했을 때 예측값의 변화를 나타낸다. 모형에 따른 조건부 관계를 모든 관측의 확정 변화나 인과효과로 단정하면 안 된다.','r47c');
add(47,3,'ARIMA 차분 차수','ARIMA(2,1,1)에서 가운데 숫자 1이 뜻하는 것은?', ['원 시계열에 적용하는 차분의 차수','자기회귀 항의 개수','이동평균 항의 개수','반드시 존재하는 군집 개수'], 'ARIMA(p,d,q)에서 d는 정상성을 위해 적용하는 비계절 차분의 차수다. p는 자기회귀 차수, q는 이동평균 차수이며 차분 정도를 확인한 뒤 정상화된 자료의 구조를 검토한다.','r47c');
add(47,3,'백색잡음','평균 0, 일정한 유한 분산, 서로 다른 시점 간 공분산 0인 시계열을 생각한다. 약정상성 관점에서 올바른 설명은?', ['백색잡음은 약정상 시계열의 한 예다','백색잡음의 평균은 시간마다 증가해야 한다','공분산이 0이면 모든 시점이 반드시 독립임을 뜻한다','정상성이 있으려면 모든 값이 동일해야 한다'], '이 조건은 약한 백색잡음을 정의하며 평균·분산·시차 공분산의 정상성 조건을 만족한다. 일반적으로 무상관과 독립은 다르며 독립까지 요구하는 정의와 구분해야 한다.','r47c');
add(47,3,'Softmax 불변성','다중 분류의 모든 로짓에 동일한 상수 c를 더한 뒤 Softmax를 적용했다. 확률은 어떻게 되는가?', ['변하지 않는다','모든 확률이 c만큼 커진다','확률의 합이 e^c가 된다','가장 큰 범주의 확률만 바뀐다'], '분자와 분모 모두 e^c가 곱해져 약분되므로 확률은 같다. 이 성질을 이용해 로짓의 최댓값을 빼면 지수 계산의 수치적 안정성을 높일 수 있다.','r47c');
add(47,3,'신경망과 로지스틱','은닉층 없이 입력의 가중합에 편향을 더하고 출력 노드 하나에 시그모이드를 적용한다. 이 구조에 가장 가까운 모형은?', ['이진 로지스틱 회귀','K-means','Apriori','완전연결 군집'], '출력이 σ(b+wᵀx)이므로 이진 로지스틱 회귀의 확률 모형과 같은 형태다. 입력에서 출력으로 연결된다는 사실만으로 같아지는 것이 아니라 선형 가중합과 시그모이드 조건이 함께 필요하다.','r47c');
add(47,3,'분류 임계값과 민감도','같은 예측 확률에서 양성 판정 임계값을 0.4에서 0.7로 높였다. 나머지 조건이 같을 때 재현율에 대한 올바른 설명은?', ['높아질 수 없으며 같거나 낮아진다','반드시 높아진다','거짓음성이 반드시 줄어든다','모든 양성이 새로 추가된다'], '임계값을 높이면 양성으로 판정하는 관측의 집합이 줄거나 같아져 참양성이 늘 수 없다. 실제 양성 수가 고정돼 있으므로 민감도·재현율은 같거나 낮아지며 특이도와의 균형을 검토한다.','r47c');
add(47,3,'EM 혼합모형','고객 데이터가 여러 정규분포의 혼합으로 표현된다고 가정하지만 각 고객의 소속 성분을 모른다. EM의 E단계에서 수행하는 일은?', ['현재 모수로 각 관측의 성분별 소속 확률을 계산한다','전체 관측을 반드시 하나의 성분으로 확정한다','모든 성분의 평균을 임의로 0으로 고정한다','데이터의 시각적 색상만 바꾼다'], 'E단계에서는 잠재 소속에 대한 조건부 기대, 즉 성분별 책임도를 계산한다. 이어지는 M단계는 이를 이용해 모수를 갱신하며 반복이 전역 최적해를 항상 보장하는 것은 아니다.','r47c');
add(47,3,'Ward 연결 기준','두 군집을 합칠 때 군집 내 제곱합 증가량이 후보별로 3.2, 7.5, 4.8이다. Ward 연결법이 먼저 선택할 후보는?', ['증가량 3.2인 후보','증가량 7.5인 후보','항상 표본 수가 가장 큰 후보','증가량과 무관하게 무작위 후보'], 'Ward는 결합으로 인한 군집 내 제곱합의 증가를 가장 작게 하는 후보를 선택한다. 단일·완전 연결법처럼 점 쌍 거리의 최솟값이나 최댓값만 사용하는 기준과 다르다.','r47c');

export const ROUND_QUESTIONS_44_47 = rows;
